#include <stdio.h>
#include <string.h>

#define N 100010
#define M 200010

int h[N],e[M],ne[M],idx;
int ans=N;
int n;
int st[N];

void add(int a,int b)
{
    e[idx]=b;
    ne[idx]=h[a];
    h[a]=idx++;
}

int dfs(int u)
{
    st[u]=1;

    int sum=1;
    int res=0;

    for(int i=h[u];i!=-1;i=ne[i])
    {
        int j=e[i];

        if(!st[j])
        {
            int s=dfs(j);
            if(s>res) res=s;
            sum+=s;
        }
    }

    if(n-sum>res)
        res=n-sum;

    if(res<ans)
        ans=res;

    return sum;
}

int main()
{
    scanf("%d",&n);

    memset(h,-1,sizeof h);

    for(int i=0;i<n-1;i++)
    {
        int a,b;
        scanf("%d%d",&a,&b);

        add(a,b);
        add(b,a);
    }

    dfs(1);

    printf("%d\n",ans);

    return 0;
}
